import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"萃","description":"东坡易传 - 萃","frontmatter":{"title":"萃","description":"东坡易传 - 萃"},"headers":[],"relativePath":"zh/classics/dongpo/046.md","filePath":"zh/classics/dongpo/046.md"}'),o={name:"zh/classics/dongpo/046.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="萃" tabindex="-1">萃 <a class="header-anchor" href="#萃" aria-label="Permalink to “萃”">​</a></h1><p>“萃”：亨。王假有廟，利見大人，亨，利貞。用大牲，吉。利有攸往。</p><p>《彖》曰：“萃”，聚也；順以說，剛中而應，故聚也。“王假有廟”，致孝享也。“利見大人，亨”，聚以正也。 “用大牲，吉，利有攸往”，順天命也。觀其所聚，而天地萬物之情可見矣。</p><p>《易》曰：“方以類聚，物以羣分。”有“聚”，必有黨；有黨，必有爭。故“萃”者，爭之大也。盍取其爻而觀之，五能“萃”二，四能“萃”初，近四而無應，則四能“萃”三；近五而無應，則五能“萃”上。此豈非其交爭之際也哉！且天下亦未有“萃”於一者也，大人者，惟能因其所“萃”而即以付之，故物有不“萃”於我，而天下之能“萃”物者，非我莫能容之，其爲“萃”也大矣。“順以說，剛中而應”者，二與五而已；而足以爲“萃”乎？曰：足矣，有餘矣！從我者納之，不從者付之其所欲從，此大人也！故“萃”有二“亨”，“萃”未有不亨者，而其未見大人也，則亨而不正；不正者，爭非其有之謂也。故曰：“利見大人，亨，聚以正也。”大人者，爲可以聚物之道而已。“王”至於有“廟”，而盡其“孝享”，非安且暇不能。物見其安且暇，安得不聚而歸之？此“聚之正”也。《易》之言薦、盥、禴、享，非正言也，皆有寄焉。“用大牲”者，猶曰用大利祿云爾。《易》曰：“何以聚人？曰財。” 所聚者大，則所用者不可小矣。天之命我爲是物主①，非以厚我也，坐而享之則過矣。故“利有攸往，順天命也”。不期而聚者，必其至情也。</p><p>【校注】 ① 天之命我：《蘇氏易傳》作“天之命者”，誤。</p><p>象曰：澤上於地，“萃”；君子以除戎器、戒不虞。</p><p>王弼曰：“聚而無防，則衆生心。”</p><p>初六：有孚不終，乃亂乃萃。若號，一握爲笑，勿恤；往無咎。象曰：“乃亂乃萃”，其志亂也。</p><p>初六之所應者，九四也；九四有信之者而“不終”，六三是也。始以無應而“萃”於四，終以四之有應，諮嗟而去之，故其象曰“萃如，嗟如。”此志亂而苟聚者也。“若號，一握爲笑”者，“號”且“笑”也，“一握”者，其聲也，“號”、“笑”雜也。君子之於禍、福審矣，故笑則不號，號則不笑；先否而後通，則先號而後笑，未有號笑雜者也。此其志已亂焉，能爲我寇哉！故“勿恤，往無咎”。</p><p>六二：引吉，無咎；孚乃利用禴。象曰：“引吉無咎”，中未變也。</p><p>陰之從陽，以難進爲吉。六二得位而安其中，不急於變，志以從上者也，故九五引之而後從。引之而後從，則其聚也固；是以吉而無復有咎。“禴”者，禮之薄者也，故用於既信之後。上以利祿聚之下，豈以利祿報之哉！故上“用大牲”而下用“禴”，以爲有重於此者矣。</p><p>六三：萃如，嗟如；無攸利，往無咎，小吝。象曰：“往無咎”，上巽也。</p><p>六三之“萃”於四，四與我、與初皆不利也，去而之上，上亦無應； “巽”而納我者也，故雖“小吝”而“無咎”。</p><p>九四：大吉，無咎。象曰：“大吉無咎”，位不當也。</p><p>非其位而有聚物之權，五之所忌也；非“大吉”，則有咎矣。</p><p>九五：萃有位，無咎；匪孚，元永貞，悔亡。象曰：“萃有位”，志未光也。</p><p>九五“萃”之主也，“萃”有四陰，而九四分其二；以位爲心者，未有能容此者也，故曰：“萃有位，無咎。”挾位以忌四爲無咎①，而己志不光矣；惟大人爲能忘位以任四。夫能忘位以任四，則四且爲吾用，而二陰者獨何往哉！“匪孚”者，非其所孚也；“元”者，始也；“元永貞”者，始既以從之，則終身爲之貞也。自六二之外，皆非我之所孚也；非我之所孚，則我不求聚，使各得永貞於其始之所從，“悔亡”之道也。</p><p>【校注】 ① 挾位：《蘇氏易傳》作“存位”，誤。</p><p>上六：齎諮涕氵夷，無咎。象曰：“齎諮涕氵夷”，未安上也。</p><p>“未安上者”，不樂在五上也。</p>',20)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
